<script>(() => {
  const intro = document.getElementById('intro');
  if (intro) {
    if (window.location.hash) intro.remove();
    else {
      intro.classList.add('show');
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) intro.classList.add('reduced');
      window.setTimeout(() => { intro.classList.add('hide'); window.setTimeout(() => intro.remove(), 450); }, 1900);
    }
  }
  document.querySelectorAll('[data-specialty]').forEach(button => button.addEventListener('click', () => {
    document.querySelectorAll('[data-specialty]').forEach(item => item.setAttribute('aria-pressed', String(item === button)));
    const status = document.getElementById('specialty-status');
    if (status) status.textContent = 'Dein Fachbereich: ' + button.dataset.specialty + '. Im Anmeldeformular kannst du diesen und weitere Fachbereiche auswählen.';
  }));

})();
</script>
